package runplan

import (
	"bytes"
	"encoding/json"
	"os"
	"reflect"
	"testing"
)

type psVector struct {
	Name    string         `json:"name"`
	Input   map[string]any `json:"input"`
	Value   map[string]any `json:"value"`
	Error   string         `json:"error"`
	Message string         `json:"message"`
}

// TestPeopleSearchConfigVectors replays testdata/people_search_vectors.json, generated by
// testdata/gen_peoplesearch_vectors.py from Python's validate_people_search_config.
func TestPeopleSearchConfigVectors(t *testing.T) {
	raw, err := os.ReadFile("testdata/people_search_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var doc struct {
		Cases []psVector `json:"cases"`
	}
	if err := dec.Decode(&doc); err != nil {
		t.Fatal(err)
	}
	if len(doc.Cases) < 40 {
		t.Fatalf("only %d vectors", len(doc.Cases))
	}
	for _, c := range doc.Cases {
		t.Run(c.Name, func(t *testing.T) {
			got, err := ValidatePeopleSearchConfig(c.Input)
			if c.Error != "" {
				if err == nil || err.Error() != c.Message {
					t.Fatalf("err = %v, want ValueError %q", err, c.Message)
				}
				if _, ok := IsPeopleSearchError(err); !ok {
					t.Fatalf("not an ErrPeopleSearch: %T", err)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error %v", err)
			}
			// Compare through JSON so numbers and key sets match the Python dict.
			gotJSON, _ := json.Marshal(map[string]any{
				"companies": got.Companies, "from_column": got.FromColumn, "titles": got.Titles,
				"seniority": got.Seniority, "geo": got.Geo,
				"max_per_company": got.MaxPerCompany, "max_searches": got.MaxSearches,
			})
			var g, w map[string]any
			d1 := json.NewDecoder(bytes.NewReader(gotJSON))
			d1.UseNumber()
			_ = d1.Decode(&g)
			wantJSON, _ := json.Marshal(c.Value)
			d2 := json.NewDecoder(bytes.NewReader(wantJSON))
			d2.UseNumber()
			_ = d2.Decode(&w)
			if !reflect.DeepEqual(g, w) {
				t.Fatalf("got %s\nwant %s", gotJSON, wantJSON)
			}
		})
	}
}
